package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8JsonGenerator#writeRaw(String, int, int)
 */
public class UTF8JsonGenerator_writeRaw_TriageGen1Test {

    private ByteArrayOutputStream out;
    private UTF8JsonGenerator generator;
    private ObjectCodec codec;
    private IOContext context;

    @Before
    public void setUp() {
        out = new ByteArrayOutputStream();
        context = new IOContext();
        codec = null; // Not needed for writeRaw
        // Using a small buffer size indirectly via the constructor or relying on default
        // To test the segmentation logic (while loop), we need to trigger the buf.length limit.
        // Since we can't easily set the internal _charBuffer size via public API, 
        // we rely on the fact that the internal buffer is typically 4KB or 8KB.
        generator = new UTF8JsonGenerator(context, 0, codec, out);
    }

    @After
    public void tearDown() throws IOException {
        generator.close();
    }

    @Test
    public void testWriteRaw_SimpleString() throws IOException {
        String text = "hello world";
        generator.writeRaw(text, 0, text.length());
        generator.flush();
        assertEquals(text, out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_WithOffsetAndLen() throws IOException {
        String text = "abcdefg";
        // Write "cde" (offset 2, length 3)
        generator.writeRaw(text, 2, 3);
        generator.flush();
        assertEquals("cde", out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_LargeString_TriggersSegmentation() throws IOException {
        // Create a string much larger than the internal char buffer (usually 4096 or 8192)
        // This forces the 'while (len > 0)' loop to run multiple times.
        int largeSize = 20000; 
        StringBuilder sb = new StringBuilder(largeSize);
        for (int i = 0; i < largeSize; i++) {
            sb.append('a');
        }
        String largeText = sb.toString();

        generator.writeRaw(largeText, 0, largeSize);
        generator.flush();

        assertEquals(largeText, out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_LargeStringWithOffset() throws IOException {
        int largeSize = 20000;
        StringBuilder sb = new StringBuilder(largeSize);
        for (int i = 0; i < largeSize; i++) {
            sb.append('b');
        }
        String largeText = sb.toString();

        // Write from index 5000, length 10000
        int offset = 5000;
        int len = 10000;
        generator.writeRaw(largeText, offset, len);
        generator.flush();

        String expected = largeText.substring(offset, offset + len);
        assertEquals(expected, out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_EmptyString() throws IOException {
        generator.writeRaw("", 0, 0);
        generator.flush();
        assertEquals("", out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_UnicodeCharacters() throws IOException {
        // Test with multi-byte UTF-8 characters to ensure correct encoding via writeRaw(buf, 0, len2)
        String text = "🚀 Java Test 🧪";
        generator.writeRaw(text, 0, text.length());
        generator.flush();
        assertEquals(text, out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testWriteRaw_InvalidOffset() throws IOException {
        String text = "test";
        generator.writeRaw(text, 10, 2);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testWriteRaw_InvalidLen() throws IOException {
        String text = "test";
        generator.writeRaw(text, 0, 10);
    }

    @Test
    public void testWriteRaw_SurrogatePairSegmentation() throws IOException {
        // This tests the logic inside the loop regarding how text is sliced.
        // We want to see if a surrogate pair is handled correctly when it falls on the buffer boundary.
        // Note: The provided source code has a comment about dropping surrogates, 
        // but the implementation shown actually just calls writeRaw(buf, 0, len2).

        // "\uD83D\uDE00" is Rocket emoji.
        // We construct a string where the surrogate pair is split by the buffer boundary.
        String emoji = "\uD83D\uDE00"; 
        String text = "abc" + emoji + "def";

        // We can't easily control the internal buffer size without reflection, 
        // but we can simulate a scenario where we write a very long string 
        // containing surrogates to ensure the while loop executes.
        StringBuilder sb = new StringBuilder();
        for(int i=0; i<5000; i++) {
            sb.append(emoji);
        }
        String longText = sb.toString();

        generator.writeRaw(longText, 0, longText.length());
        generator.flush();

        assertEquals(longText, out.toString(StandardCharsets.UTF_8.name()));
    }
}
